From c3a1fdb2c13c9f3d908f3c237e4bf2d804c765b5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:32:14 +0100
Subject: [PATCH] tooltiparea: allow tooltips to ignore the global tooltip
 setting

Turning off panel and widget tooltips in System Settings also hid any
tooltip that is not just descriptive text, like window previews. Add an
ignoreGlobalSetting property so these can keep showing when hovered.

BUG: 468223
---
 src/declarativeimports/core/tooltiparea.cpp |  9 ++++++---
 src/declarativeimports/core/tooltiparea.h   | 12 ++++++++++++
 2 files changed, 18 insertions(+), 3 deletions(-)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..38ef623c1 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -21,6 +21,8 @@

 using namespace Qt::Literals;

+static constexpr int s_defaultInterval = 700;
+
 ToolTipDialog *ToolTipArea::s_dialog = nullptr;
 int ToolTipArea::s_dialogUsers = 0;

@@ -33,6 +35,7 @@ ToolTipArea::ToolTipArea(QQuickItem *parent)
     , m_active(true)
     , m_interactive(false)
     , m_hideOnClick(true)
+    , m_ignoreGlobalSetting(false)
     , m_timeout(-1)
     , m_usingDialog(false)
 {
@@ -72,7 +75,7 @@ void ToolTipArea::settingsChanged(const KConfigGroup &group, const QByteArrayLis

 void ToolTipArea::loadSettings(const KConfigGroup &cfg)
 {
-    m_interval = cfg.readEntry("Delay", 700);
+    m_interval = cfg.readEntry("Delay", s_defaultInterval);
     m_tooltipsEnabledGlobally = (m_interval > 0);
 }

@@ -361,7 +364,7 @@ void ToolTipArea::hoverEnterEvent(QHoverEvent *event)
     Q_UNUSED(event)
     setContainsMouse(true);

-    if (!m_tooltipsEnabledGlobally) {
+    if (!m_tooltipsEnabledGlobally && !m_ignoreGlobalSetting) {
         return;
     }

@@ -383,7 +386,7 @@ void ToolTipArea::hoverEnterEvent(QHoverEvent *event)
             }
         }
     } else {
-        m_showTimer.start(m_interval);
+        m_showTimer.start(m_tooltipsEnabledGlobally ? m_interval : s_defaultInterval);
     }
 }

diff --git a/src/declarativeimports/core/tooltiparea.h b/src/declarativeimports/core/tooltiparea.h
index 6951de824..a2cf31396 100644
--- a/src/declarativeimports/core/tooltiparea.h
+++ b/src/declarativeimports/core/tooltiparea.h
@@ -148,6 +148,16 @@ class ToolTipArea : public QQuickItem
      */
     Q_PROPERTY(int timeout MEMBER m_timeout WRITE setTimeout)

+    /*!
+     * \qmlproperty bool ToolTipArea::ignoreGlobalSetting
+     * If set to true, the tooltip will show even when panel and widget tooltips
+     * are disabled in the system settings. This is appropriate for tooltips that
+     * are not merely descriptive, such as window previews.
+     * The default is false.
+     * \since 6.9
+     */
+    Q_PROPERTY(bool ignoreGlobalSetting MEMBER m_ignoreGlobalSetting NOTIFY ignoreGlobalSettingChanged)
+
 public:
     explicit ToolTipArea(QQuickItem *parent = nullptr);
     ~ToolTipArea() override;
@@ -227,6 +237,7 @@ Q_SIGNALS:
     void activeChanged();
     void interactiveChanged();
     void hideOnClickChanged();
+    void ignoreGlobalSettingChanged();
     /*!
      * \qmlsignal ToolTipArea::aboutToShow
      *
@@ -264,6 +275,7 @@ private:
     bool m_active;
     bool m_interactive;
     bool m_hideOnClick;
+    bool m_ignoreGlobalSetting;
     int m_interval;
     int m_timeout;

-- 
